def card(m):
    links=f'<a href="{m["src"]}">Odds/form source ↗</a> · <a href="{m["fix"]}">Fixture ↗</a>'+(f' · <a href="{m["src2"]}">2nd source ↗</a>' if m.get("src2") else "")
    return f'''<article class="card" id="{m['id']}"><div class="small">{m['date']} · {m['event']}</div>
<div>{m['a']} <b>vs</b> {m['b']}</div><div class="pick">✅ PICK: {m['pick']} <span class="pct">{m['pickpct']}%</span></div>
<div class="bar"><i style="width:{m['pa']}%"></i></div><div class="small">{m['a']} {m['pa']}% · {m['b']} {m['pb']}% · {m['own']}</div>
<p><span class="badge {m['tier']}">TIER {m['tier']}</span> <span class="small">{m['conf']}</span></p>
<details><summary>Why / sources</summary><p class="small">{m['odds']}</p><p class="small">{links}</p></details></article>'''
